:root{--neon:#8cff00;--dark:#11131a}body{background:#f4f6f8;color:#20232a}.navbar-brand{letter-spacing:1px}.btn-neon{background:var(--neon);color:#111;font-weight:700;border:0}.btn-neon:hover{background:#78df00;color:#111}.hero{background:linear-gradient(120deg,#10131d,#252b3b);color:white;border-radius:22px;padding:3rem}.hero span{color:var(--neon)}.product-card{border:0;border-radius:16px;overflow:hidden;box-shadow:0 5px 20px #17203312;height:100%;transition:.2s}.product-card:hover{transform:translateY(-4px)}.product-img{height:190px;object-fit:cover;background:#e7eaf0}.price{font-size:1.25rem;font-weight:800;color:#202b18}.footer{background:#11131a}.form-card{max-width:520px;margin:2rem auto;background:white;padding:2rem;border-radius:18px;box-shadow:0 5px 25px #17203312}.admin-title{border-left:5px solid var(--neon);padding-left:14px}.table{background:white}
